ta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 6","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"4928d79c-9948-504a-93be-3267f5c5faed","text":"Replace the entire publication","isCorrect":false,"position":0},{"id":"3b32ca8d-bc44-54e1-80dd-1d100421f0a1","text":"List borrower names","isCorrect":false,"position":1},{"id":"603a410b-11fd-5e59-a9c5-80661bb6d82c","text":"Give geographic coordinates","isCorrect":false,"position":2},{"id":"1448af39-dd88-5a7a-98a3-e0d67a072ad6","text":"Describe the scope and topics without reporting full findings","isCorrect":true,"position":3}]},{"id":"cc1791f7-0706-5adb-a2bf-f2a1f25645b8","position":134,"prompt":"A bibliography lists a journal article but omits volume, issue, pages and DOI. Why is verification difficult?","explanation":"Complete bibliographic elements improve identification and retrieval.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Guides to Published Information and Bibliographic Skills","fingerprint":"6259635890cc1d12fcf0ac0e6b1a7b6bebef0808aa85537f2893aa1016d33ed0","studyRef":{"sourceLabel":"GNS 113 module, Study Session 6","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 6","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"0476a20f-0c10-51b1-ad60-a113302b46ef","text":"Journal articles have no authors","isCorrect":false,"position":0},{"id":"2bef37df-6c92-5daf-a698-314336c41cce","text":"A DOI is the only valid citation element","isCorrect":false,"position":1},{"id":"6f7df177-811a-5f05-b694-8fe69ba11775","text":"The citation lacks details needed to distinguish and locate the article","isCorrect":true,"position":2},{"id":"ba6e286d-2452-5d6c-807e-174639a87d4f","text":"Article titles are never searchable","isCorrect":false,"position":3}]},{"id":"597c8832-f8e5-5dc1-86f8-363cd1e2bc5e","position":135,"prompt":"A student treats an abstract as proof of a paper's detailed methodology. What is the main problem?","explanation":"Abstracts support relevance screening but rarely replace critical reading of the complete study.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Guides to Published Information and Bibliographic Skills","fingerprint":"7a7c6acf1f37eb6c76a35f1e76255c2e6c3558bc77d04c91c55dd98fc486e6b9","studyRef":{"sourceLabel":"GNS 113 module, Study Session 6","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 6","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"99efcf5c-b9fe-5ba1-a31a-95c6e1f7a5c9","text":"Full texts never explain methods","isCorrect":false,"position":0},{"id":"2aaf92d1-879a-5461-91da-a13494611c43","text":"An abstract may omit limitations and methodological detail found in the full text","isCorrect":true,"position":1},{"id":"9abe45b3-24f7-5e69-84e5-0c0a610e40bc","text":"Abstracts are always fictional","isCorrect":false,"position":2},{"id":"3dad0e2f-eca1-56b6-ac65-67376a951c69","text":"The title contains more methods than the article","isCorrect":false,"position":3}]},{"id":"22236d93-7aae-54d9-89a8-0967bc9f56c3","position":136,"prompt":"What is a DOI?","explanation":"A Digital Object Identifier helps reliably identify and link to an article or other object.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Guides to Published Information and Bibliographic Skills","fingerprint":"80bc802c25a938d3c6ab8b6f0553bea1621e6e0e4d0004a88095b363065e0e93","studyRef":{"sourceLabel":"General GNS 113 enrichment: Guides to Published Information and Bibliographic Skills","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: Guides to Published Information and Bibliographic Skills","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"febc4702-5d97-578d-83fd-1ff038bc98fe","text":"A persistent identifier assigned to a digital scholarly object","isCorrect":true,"position":0},{"id":"9a151fe9-fa8b-50bd-838b-e6fc5e7633c8","text":"A temporary library password","isCorrect":false,"position":1},{"id":"fa069b49-b45d-5a0c-ae54-ff914deeea22","text":"A physical shelf mark only","isCorrect":false,"position":2},{"id":"f2327792-3f5c-5313-bd3f-50f8598f7c2b","text":"A book's selling price","isCorrect":false,"position":3}]},{"id":"8b814093-adac-59a1-8b8a-4c446e2cbfa8","position":137,"prompt":"Which information is normally essential when citing a journal article?","explanation":"A usable citation identifies both the work and the container in which it was published.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Guides to Published Information and Bibliographic Skills","fingerprint":"095f67ec83df641a831177e58afa0b336be73e1fdf1417628b7851e0c091be18","studyRef":{"sourceLabel":"General GNS 113 enrichment: Guides to Published Information and Bibliographic Skills","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: Guides to Published Information and Bibliographic Skills","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"f956e952-f352-593d-91db-f265d9303353","text":"Only the colour of the webpage","isCorrect":false,"position":0},{"id":"dac1dd37-cca8-5194-b525-5c53c84a1f72","text":"The borrower's name","isCorrect":false,"position":1},{"id":"276f611e-ec63-5aed-b366-172cd4b36999","text":"The library opening time","isCorrect":false,"position":2},{"id":"e5546aea-9a7c-5324-85ca-d907e4697590","text":"Author, article title, journal, year and publication details","isCorrect":true,"position":3}]},{"id":"0078e3b5-7888-5352-adea-acf82a56bf6e","position":138,"prompt":"A DOI link fails, but the DOI string is available. What is the strongest recovery strategy?","explanation":"Persistent identifiers can be resolved or searched even when one hyperlink implementation fails.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Guides to Published Information and Bibliographic Skills","fingerprint":"caf8d225d8cae62b280816121981c06c832166a496ef5e28eec72407141b7617","studyRef":{"sourceLabel":"General GNS 113 enrichment: Guides to Published Information and Bibliographic Skills","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: Guides to Published Information and Bibliographic Skills","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"a102cb98-8be5-5ffd-9e43-2552649c3f85","text":"Invent a replacement DOI","isCorrect":false,"position":0},{"id":"37d31e0b-554f-589d-a408-ee0388253095","text":"Remove the source from the bibliography without checking","isCorrect":false,"position":1},{"id":"5eadceba-e212-52e8-a009-456b6a7c56a8","text":"Search the DOI through a resolver or scholarly search tool","isCorrect":true,"position":2},{"id":"c10b0c54-4502-54b6-acaf-81701cdc9b93","text":"Assume the article was never published","isCorrect":false,"position":3}]},{"id":"3dbeb246-2f4f-5c85-bf4f-374fb853e39b","position":139,"prompt":"A citation generator produces a polished reference with the wrong author. What should the student do?","explanation":"Automated citation output must be verified for bibliographic accuracy.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Guides to Published Information and Bibliographic Skills","fingerprint":"f56fda43d46afa4037198a7c1b37ed12cd5f7011fa49d34b15a8270542bd631b","studyRef":{"sourceLabel":"General GNS 113 enrichment: Guides to Published Information and Bibliographic Skills","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: Guides to Published Information and Bibliographic Skills","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"cbe316c8-66e5-59cc-be12-16cf701e9950","text":"Delete every citation","isCorrect":false,"position":0},{"id":"a50c807c-0401-52b1-a7f4-de0de6ca0c62","text":"Correct it against the original source metadata","isCorrect":true,"position":1},{"id":"ff8763d1-c71d-5a4c-8cd5-f7b149f65510","text":"Keep it because formatting tools cannot err","isCorrect":false,"position":2},{"id":"8399717e-2d85-5085-ad51-68522a224cc0","text":"Replace the author with the student's name","isCorrect":false,"position":3}]},{"id":"8f93181d-bdb6-52ca-a721-61210b244ce8","position":140,"prompt":"What is the main purpose of a current-awareness service?","explanation":"Current-awareness services expose users to newly available and recently published information.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Current Awareness and Research Discovery","fingerprint":"e951c2d5c76380d7da94b4df9b6fc60a2464ee7d5aba64b3aabcdffb697e3513","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"54765967-e639-5ecd-b52d-610ba408ab55","text":"To alert users quickly to recent information in their fields","isCorrect":true,"position":0},{"id":"165935e8-8f88-514c-873b-cc35e48d4088","text":"To replace every older publication","isCorrect":false,"position":1},{"id":"cee81d5d-572f-5e19-9426-82e21bb03cec","text":"To collect library fines","isCorrect":false,"position":2},{"id":"d43f00bf-eeed-5dd9-9a17-42d6e13c1442","text":"To classify furniture","isCorrect":false,"position":3}]},{"id":"7fa19558-501b-598e-97fc-8505e03ade79","position":141,"prompt":"According to the module, current-awareness service is closely associated with what term?","explanation":"The module links current awareness with Selective Dissemination of Information, often abbreviated SDI.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Current Awareness and Research Discovery","fingerprint":"a5c7cf957bac30a04b432354cdaa9e9396896680c26761543bee3f4d50eef0a3","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"9d631646-b832-5756-87b8-52f42d6fb099","text":"Retrospective Conversion of Records","isCorrect":false,"position":0},{"id":"8aa3696e-ea79-52bd-ace5-66ea3b79ddc6","text":"Interlibrary Shelving","isCorrect":false,"position":1},{"id":"10c2475c-0232-566b-aa73-29e002fcf1e4","text":"Document Binding Service","isCorrect":false,"position":2},{"id":"717e71e5-d1b8-52c3-a15d-9bd5ff9c8a92","text":"Selective Dissemination of Information","isCorrect":true,"position":3}]},{"id":"97e9b84e-0d15-5de1-ab5b-4ad90d9a31b5","position":142,"prompt":"Which users commonly benefit from a current-awareness profile?","explanation":"Services can be tailored to a researcher's or group's interest profile.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Current Awareness and Research Discovery","fingerprint":"01c15fe5b11d5c6becba8ab7582d4d6f1f7e26620ef0ad420413a0f7b5d068f0","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"8a43c166-2f2e-571b-b162-cc4553bba352","text":"Publishers' delivery drivers","isCorrect":false,"position":0},{"id":"4d8f3812-5a20-50d2-9720-67fd1358720a","text":"Library furniture suppliers","isCorrect":false,"position":1},{"id":"7baab40a-71c6-5633-9887-050075c13a54","text":"Individuals or groups with defined subject interests","isCorrect":true,"position":2},{"id":"172bcd99-a6c7-58a7-ba0f-3f9c4148bcc7","text":"Only people with no information needs","isCorrect":false,"position":3}]},{"id":"6a0a770b-c832-5ef7-8159-abec21fc7d1b","position":143,"prompt":"What does a Current Contents service reproduce?","explanation":"Contents-page reproduction lets researchers scan newly published articles quickly.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Current Awareness and Research Discovery","fingerprint":"df1a3fe9c688a9456e077034f48569c89400a3111483addb828879495d4a8e39","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"e1821da9-0849-5bf2-bd43-20621987e664","text":"The national census","isCorrect":false,"position":0},{"id":"37f36d9a-8519-5151-8236-b79f77b4559c","text":"Tables of contents from recent journals","isCorrect":true,"position":1},{"id":"98b1c483-0fdc-54a9-8fb6-50ff04988a29","text":"Every library user's loan record","isCorrect":false,"position":2},{"id":"329ef1bd-163d-534f-a344-094e90e19b56","text":"Complete textbooks only","isCorrect":false,"position":3}]},{"id":"c98a2a52-cbcf-5519-af1f-13e4c11af33a","position":144,"prompt":"How often did the module describe the Current Contents series as appearing?","explanation":"The cited Current Contents sections were issued weekly.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Current Awareness and Research Discovery","fingerprint":"954b7e6a3ce73b461061efd25cbbd4a5e45e7e362e9ec84127d1b4a95f78d54f","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"791c79c9-5da8-5e2f-9708-833a6a6f7337","text":"Weekly","isCorrect":true,"position":0},{"id":"9d10f895-4f74-5719-8f5c-8ddfdf72256d","text":"Once every ten years","isCorrect":false,"position":1},{"id":"f7d992e7-64c7-5364-a10d-589b6ed8973e","text":"Hourly","isCorrect":false,"position":2},{"id":"8d57632d-0656-5af8-b304-b176772e1a26","text":"Only when a library closes","isCorrect":false,"position":3}]},{"id":"b6c756ad-64b2-50a2-be18-02d65567535f","position":145,"prompt":"What is a review journal primarily devoted to publishing?","explanation":"Review journals publish signed evaluative accounts of new works.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Current Awareness and Research Discovery","fingerprint":"b11b75d28d30aef4fb20c494e38a9dbc2516a9c4e208b882d42f7d373546711c","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"42588f9f-e634-5fec-8dae-5ba2b6048491","text":"Raw circulation statistics","isCorrect":false,"position":0},{"id":"7e5ac2af-d598-5448-8626-a8c75cfdd4a6","text":"Only classified advertisements","isCorrect":false,"position":1},{"id":"1145225a-d4d2-5b3d-a7d3-26cd014e6b9f","text":"Shelf numbers without reviews","isCorrect":false,"position":2},{"id":"2cb7263e-2ff4-5304-87e7-0923c6021381","text":"Evaluations of new books and other publications","isCorrect":true,"position":3}]},{"id":"48a14fb8-316e-5403-a7a5-ea7f21e3b450","position":146,"prompt":"Why are journal tables of contents useful for current awareness?","explanation":"Scanning contents pages shortens the delay in discovering new literature.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"b027ee4fa2f26f7d41baec1d06e93d22ea166a3894f951f2fa71558c1521689f","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"38f26e28-ca91-5d57-ac25-be5af87fd146","text":"They replace the complete articles","isCorrect":false,"position":0},{"id":"5c72f42d-a49f-5c6d-81fa-4fc159da7706","text":"They contain no bibliographic information","isCorrect":false,"position":1},{"id":"45f44458-49a5-5b88-9d41-81cf1906ce71","text":"They reveal new article titles before conventional indexes may be updated","isCorrect":true,"position":2},{"id":"282e7b5f-f413-5e96-ba05-5ad05dada425","text":"They guarantee every article is correct","isCorrect":false,"position":3}]},{"id":"85670ade-8bcc-527d-a441-9fd616135a8b","position":147,"prompt":"How does an interest profile improve selective dissemination?","explanation":"A profile improves relevance by specifying topics, authors, journals or other preferences.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"3ca7eb9fa21d0229888b2f34c4d023e619628b30b27b0b6cba9f261b26333c7c","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"f854b1bc-da49-5ebf-8f5b-8224174913f3","text":"It limits searching to one author forever","isCorrect":false,"position":0},{"id":"d251e9dd-cd53-51e2-9f03-9746e24b4d99","text":"It matches alerts to the user's subjects and needs","isCorrect":true,"position":1},{"id":"547c3976-b69e-574d-ac88-6d1aad5537be","text":"It sends every user identical unrelated material","isCorrect":false,"position":2},{"id":"aa18b2ac-f230-513d-847c-b88de8960bd7","text":"It removes all recent publications","isCorrect":false,"position":3}]},{"id":"254b75ad-9792-5452-8465-c014fb636002","position":148,"prompt":"What is the main benefit of a review journal to a potential reader?","explanation":"A review summarizes and critically assesses a new publication.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"20120c6599fdf9951868dcf8b8e84ddfa72913f66570f5fdec8aa6f93d124169","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"dccc1329-a3d4-5ccb-8bd2-6dcf39bda422","text":"It helps the reader judge whether a publication is worth consulting","isCorrect":true,"position":0},{"id":"c9c88cab-2e22-5fe0-ba87-adba871c626f","text":"It supplies a borrower's password","isCorrect":false,"position":1},{"id":"1b94238a-d9b8-5eee-82b1-83a9263b4e70","text":"It guarantees the reviewed work is available","isCorrect":false,"position":2},{"id":"5d807fdf-1a91-56b2-8a31-7ecc2302dd93","text":"It replaces the book permanently","isCorrect":false,"position":3}]},{"id":"f0c70285-1d0c-5e6d-895a-6e75995db3b8","position":149,"prompt":"How can review journals assist library collection development?","explanation":"Professional reviews help librarians assess quality, relevance and audience.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"8459ae2f2edc168cbe3ca02a67fe93e47361abc7a91670853d31621e251d6aa3","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"d5b8e1c4-86db-527c-a035-12073371a372","text":"They automatically purchase every book","isCorrect":false,"position":0},{"id":"d0860d2c-3a97-5ae1-8a3b-f37056dd0e40","text":"They eliminate budget constraints","isCorrect":false,"position":1},{"id":"2a3087e7-e9e7-50fa-abef-21953c328cc3","text":"They classify all books by size","isCorrect":false,"position":2},{"id":"e6554e72-75e6-534c-b80d-f076eb2fa4bd","text":"They provide evaluations that inform selection decisions","isCorrect":true,"position":3}]},{"id":"cc43aacd-79f2-58f9-955b-4b07982f3d02","position":150,"prompt":"A medical researcher needs immediate notice of articles on one narrow disease. Which service is most suitable?","explanation":"A targeted alert continuously matches new records against a precise interest profile.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"cd59c4b6c7e71af2589089e2172f09f86b9a064c5c8dc44339691f0d53bf9f92","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"a19c32b5-7bad-54cf-ae51-bfc8052992cd","text":"An annual yearbook only","isCorrect":false,"position":0},{"id":"c67f9fd6-1e2f-5af8-bae0-d02d6a2c2036","text":"A random shelf search","isCorrect":false,"position":1},{"id":"9c941e66-5aed-5349-b8af-84c9871c4bde","text":"A tailored SDI or database alert","isCorrect":true,"position":2},{"id":"68c8a5f4-cc0f-5732-8906-1d9649df161a","text":"A general atlas","isCorrect":false,"position":3}]},{"id":"38b90c04-96e3-5c79-81b8-5a6a525ea809","position":151,"prompt":"Which feature makes current-awareness service especially important in a special library?","explanation":"Focused organizations depend on timely specialist information for decisions and research.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"1b2c62e6b812ce9301fe47b42406627fa842ae93b7dc45050a4546f55d48ec86","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"be8deb70-b16b-52ff-b32e-6607951f3884","text":"They cannot distribute alerts","isCorrect":false,"position":0},{"id":"9f85e6d2-3ec9-509a-81e9-903f51de8f2f","text":"Users often need recent information in a focused field","isCorrect":true,"position":1},{"id":"5cfe4e7c-c9a7-5515-b850-c73b8b9b4685","text":"Special libraries contain no current publications","isCorrect":false,"position":2},{"id":"edb6a1dd-d510-55ff-9ba1-14aeaf179ffd","text":"Their users never conduct research","isCorrect":false,"position":3}]},{"id":"e0a109bf-eb85-5bf1-8257-99c0d9625653","position":152,"prompt":"What is the difference between a book review and an abstract?","explanation":"Reviews contain critical judgment, whereas abstracts primarily represent the source concisely.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"4f9aaa972bb520f63c6644234d6da591e47e31805d4e889982ae41a294c55e4c","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"a58e42e3-559d-590c-8813-cd118a773584","text":"A review evaluates; an abstract mainly summarizes","isCorrect":true,"position":0},{"id":"95d45642-fdb5-5518-a9b0-fbb052a244b9","text":"An abstract evaluates while a review only lists pages","isCorrect":false,"position":1},{"id":"827eb0e7-3f3d-52dc-8178-29e4c379f85c","text":"They are always identical","isCorrect":false,"position":2},{"id":"77b10027-ebaa-565c-8c47-b6c2f4fd3eef","text":"Neither describes content","isCorrect":false,"position":3}]},{"id":"5610fb59-8635-5efd-b689-5ef9f1c31a5b","position":153,"prompt":"Why should a current-awareness alert include enough citation information?","explanation":"Actionable alerts need reliable metadata or links to the underlying publication.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"82b612ec5b633c6beaa68ec776a16571fd5ee31b5e3d8cc6cc4d93a73c239f69","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"26247d17-d78c-5699-adf7-b8c08cd74d1a","text":"So it can replace the item's content","isCorrect":false,"position":0},{"id":"9d6f6f62-ae1b-575a-822f-90626785f2a8","text":"To hide the publication source","isCorrect":false,"position":1},{"id":"4ab53c5d-c6be-5618-bc3d-801a4e3c2906","text":"To prevent users from following it","isCorrect":false,"position":2},{"id":"fd3995c0-1a7f-59e1-9156-16a902dd586d","text":"So users can identify and retrieve the announced item","isCorrect":true,"position":3}]},{"id":"9d516705-bd1f-55bc-8622-df2931dffff2","position":154,"prompt":"A weekly alert returns 500 mostly irrelevant records. What is the best improvement?","explanation":"A more precise profile reduces noise while preserving timely discovery.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Current Awareness and Research Discovery","fingerprint":"2fec9764ce51633a003f62f9d299be5a264ec17ad101b1acc4094f66d6030edb","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"108a9faf-d86c-534a-9aa9-209dc47ca9c7","text":"Delete all subject terms","isCorrect":false,"position":0},{"id":"9c2591e6-09e7-543f-86fd-b496456e17a2","text":"Stop checking relevance","isCorrect":false,"position":1},{"id":"c02b1637-e90c-5743-911e-c9d28f7cf342","text":"Refine the interest profile with focused terms, exclusions and source limits","isCorrect":true,"position":2},{"id":"e2f31f45-8e69-5422-bc6b-0c3af98f956d","text":"Increase the alert to every database record","isCorrect":false,"position":3}]},{"id":"496ab9b9-765d-50d7-94e8-80ccde801a60","position":155,"prompt":"A review praises a book but was written by its publisher without disclosure. Which concern is strongest?","explanation":"Undisclosed commercial involvement can compromise the independence of evaluation.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Current Awareness and Research Discovery","fingerprint":"77b2405cdc75c2c89b0083078d62e71ad5d6fe6533cabb1b3face49e91016eec","studyRef":{"sourceLabel":"GNS 113 module, Study Session 7","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 7","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"c850fa17-f697-5b0f-8684-89bca17957a9","text":"The review is recent","isCorrect":false,"position":0},{"id":"97cd7ed0-0224-5eb3-956a-a6a8f1b896db","text":"Potential conflict of interest","isCorrect":true,"position":1},{"id":"f14c0652-255d-5465-b79f-f2de71084282","text":"The review contains a title","isCorrect":false,"position":2},{"id":"0bde6d09-3b57-594c-a820-fd20ed7a7a9e","text":"The book has an ISBN","isCorrect":false,"position":3}]},{"id":"72d7b88a-35e5-578f-ace6-01aa213a589f","position":156,"prompt":"What is an RSS feed?","explanation":"RSS can deliver new posts, issues or search updates to a feed reader.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Current Awareness and Research Discovery","fingerprint":"aef6f84932b0646efe3913818dddf8b5f8fd7c607693764c7b0c7f30f04f2b0d","studyRef":{"sourceLabel":"General GNS 113 enrichment: Current Awareness and Research Discovery","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: Current Awareness and Research Discovery","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"95fe4806-282d-55a8-a822-400b7d9ef481","text":"A subscribable stream of updates from a website or publication","isCorrect":true,"position":0},{"id":"94ee6bd5-b68a-590d-8812-6bfbe9f172dc","text":"A library classification number","isCorrect":false,"position":1},{"id":"b2b2057a-bc2b-59d9-a81e-82a2a1598b5d","text":"A printed borrower's ticket","isCorrect":false,"position":2},{"id":"42a6031f-5da1-52b3-ba98-543f1e7fdb15","text":"A method of book repair","isCorrect":false,"position":3}]},{"id":"a3694752-e2f8-568b-a253-98d8aabe203c","position":157,"prompt":"What does a saved-search alert in a database do?","explanation":"Saved alerts automate current discovery using the user's search strategy.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Current Awareness and Research Discovery","fingerprint":"2057aa6f088dda583a403e315e5677c1e8ea9aab7870ce8bc77aa98d9d7d3b5a","studyRef":{"sourceLabel":"General GNS 113 enrichment: Current Awareness and Research Discovery","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: Current Awareness and Research Discovery","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"9872f35f-4ecc-5046-a671-4b0960a59c0f","text":"Deletes old results automatically","isCorrect":false,"position":0},{"id":"34186da6-8ee8-5831-8e68-c4a1f5516ae3","text":"Downloads every article illegally","isCorrect":false,"position":1},{"id":"815b4032-06b4-584b-8d59-61b2c94c1ba9","text":"Changes article authors","isCorrect":false,"position":2},{"id":"b3cafcd9-cffb-5196-ae0a-103043522ed5","text":"Reruns a query periodically and notifies the user of new matches","isCorrect":true,"position":3}]},{"id":"f7aaa2f1-38f5-58e1-86c3-58b26a8e54fd","position":158,"prompt":"A researcher needs the newest systematic reviews, not every new mention. Which alert design is best?","explanation":"Structured filters align the alert with the evidence type and recency required.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Current Awareness and Research Discovery","fingerprint":"e658fc0019165dd527ba13b4fbcf44ff33e103d53426850375245b06f8f8f513","studyRef":{"sourceLabel":"General GNS 113 enrichment: Current Awareness and Research Discovery","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: Current Awareness and Research Discovery","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"d0b5f41f-e3b8-521e-9784-feb4006460ce","text":"Add many unrelated OR terms","isCorrect":false,"position":0},{"id":"bc8ee129-b0ad-5d23-b8bc-82a2b0fe98f2","text":"Remove the topic entirely","isCorrect":false,"position":1},{"id":"0a66cc26-8af3-57bc-9e3d-beb85cf5a7ed","text":"Combine the topic with publication-type filters and a suitable date limit","isCorrect":true,"position":2},{"id":"63e1704f-cff0-529f-9668-55d823988f73","text":"Use only the word research","isCorrect":false,"position":3}]},{"id":"5ae82c36-dbe9-531c-80e1-3973c04b8e00","position":159,"prompt":"Why should a researcher periodically review a long-running alert strategy?","explanation":"Updating the profile maintains recall and precision as a field evolves.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Current Awareness and Research Discovery","fingerprint":"0495fc507318306090fd5a4f373f9960af84016d1d0b96791a3da72a399a2027","studyRef":{"sourceLabel":"General GNS 113 enrichment: Current Awareness and Research Discovery","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: Current Awareness and Research Discovery","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"2d0dba94-94cc-5a43-a9e4-6292dba52003","text":"Every new article uses identical vocabulary","isCorrect":false,"position":0},{"id":"345355a3-94ee-5f8c-868a-8f283a34d844","text":"Terminology, databases and research interests can change","isCorrect":true,"position":1},{"id":"177b4d44-875b-5082-8de9-8d068715b6a7","text":"Search terms never change meaning","isCorrect":false,"position":2},{"id":"e799d464-6b9b-535f-a86a-352a4355fb9b","text":"Alerts become legally invalid after one week","isCorrect":false,"position":3}]},{"id":"9bd116b9-cde7-5e5b-919a-030f82899950","position":160,"prompt":"Who does the module state may use library facilities?","explanation":"Registration establishes authorized access and accountability.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"e3e83c2f6652d09bcfd563cf2cb662abcc70cdadba213a8a9047f7cefe16cf4d","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"ed47e3d2-d652-5597-9a32-e192ddd95924","text":"Registered users and students","isCorrect":true,"position":0},{"id":"efdfe6da-5d9c-5ca3-8472-ece1a227f8b4","text":"Anyone removing materials without registration","isCorrect":false,"position":1},{"id":"e970d18d-0a86-5d24-afd1-5a8fa60fb4ee","text":"Only publishers","isCorrect":false,"position":2},{"id":"ae6fbfe5-b956-5113-92e3-66b8051466c5","text":"Only library vendors","isCorrect":false,"position":3}]},{"id":"51921866-6f4c-508e-80f3-e8bfe3eb7fb5","position":161,"prompt":"What document may be issued to a registered user for borrowing access?","explanation":"A borrower's card identifies an authorized library user.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"b78498b6a909faef51a1085a967924df5936b8dc03e00d15097576cf53fdc543","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"d41aa68b-5448-52fb-a4c3-e643f5ec6964","text":"A publishing licence","isCorrect":false,"position":0},{"id":"5be85741-a281-50e8-a570-57914d043706","text":"A catalogue drawer","isCorrect":false,"position":1},{"id":"f486746b-cc34-5aa7-99dc-a363eb45f00c","text":"A bookshop receipt","isCorrect":false,"position":2},{"id":"39ae4c4d-03e9-546c-9b10-fa7017dcba6c","text":"Library or borrower's card","isCorrect":true,"position":3}]},{"id":"b2359e18-e80e-5577-992f-3ebf1dfae1c5","position":162,"prompt":"What behaviour does the module require inside the library?","explanation":"Quiet conduct supports study and avoids disturbing other users.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"5a6a514f07edd0c4ebbf978210c024a108169fc8a3d32989584b83080b740d5a","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"09341089-bbe8-5019-aa3c-aa196e14cf52","text":"Smoking near shelves","isCorrect":false,"position":0},{"id":"9191dafa-b6d4-5807-bd32-348579ec4ef3","text":"Eating over books","isCorrect":false,"position":1},{"id":"75eb6144-0de8-56f6-a6f7-c6d666637fda","text":"Maintaining silence","isCorrect":true,"position":2},{"id":"d7379497-58af-5514-a7a4-2f5a785efad5","text":"Playing loud music","isCorrect":false,"position":3}]},{"id":"b7009899-693b-5fb4-81f1-993385e67237","position":163,"prompt":"What should be done with books consulted inside the library?","explanation":"Staff can reshelve consulted items correctly and record use where needed.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"33f7865bc12de3d4eb141086130ec4eb7093a3917578be1686091ebb3bac6d26","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"6d83741f-5a3b-5e01-b533-05a6abeea346","text":"Write notes inside them","isCorrect":false,"position":0},{"id":"f3ef10b8-75c3-56f7-8b8d-e03a6ea190b5","text":"Leave them on the reading table for staff","isCorrect":true,"position":1},{"id":"c34c6a86-83fb-53f7-9ca7-2031fbf9d6c8","text":"Hide them on another shelf","isCorrect":false,"position":2},{"id":"3997bbef-fced-5493-97e4-cb79cf04e2d1","text":"Take them home without charging","isCorrect":false,"position":3}]},{"id":"e2ae21a4-8a95-537a-afa2-2f9f5da9eed6","position":164,"prompt":"What must happen before a circulating item leaves the library?","explanation":"Charging records the loan and establishes responsibility for return.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"64654bb54e6a426264ff042498d552e1614ca2c04e026e2918ac907aad1c229c","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"10eefb59-6a57-5c70-b553-bb0bb8d03d83","text":"It must be properly charged out","isCorrect":true,"position":0},{"id":"17f3bddc-47c4-51f1-8123-579e3a43c2f2","text":"Its catalogue record must be deleted","isCorrect":false,"position":1},{"id":"217e121b-bc9c-53ef-94b2-710553edd847","text":"Its call number must be removed","isCorrect":false,"position":2},{"id":"bd4c9602-31bd-542f-991c-54dfed2ab162","text":"It must be marked by the user","isCorrect":false,"position":3}]},{"id":"d603a19d-a419-59cc-acc6-a71f85197fec","position":165,"prompt":"Which materials does the module say should not be removed from the library?","explanation":"High-demand or consultation collections are designated for in-library use.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"afa2ead335029163dd8eb87c478c4ea83151219229e827625b52de4269523db5","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"c4849f38-4c6a-5018-b9f0-6fa4cefd34d8","text":"Every circulating textbook","isCorrect":false,"position":0},{"id":"6d912944-290f-5bdf-9c04-d168b3fe4a19","text":"The user's personal notebook","isCorrect":false,"position":1},{"id":"d17d201d-25c2-5453-a0b1-6c730808bcda","text":"All photocopies","isCorrect":false,"position":2},{"id":"e45184c6-49bb-5c3c-8de0-5f4c09076ca7","text":"Reference, serial and reserved materials","isCorrect":true,"position":3}]},{"id":"b65b05b5-498d-5f6e-8fbe-ffa9e7a4c259","position":166,"prompt":"Why are overdue fines imposed?","explanation":"Keeping items beyond their due date prevents other users from accessing them.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"bfa3ccd559e5ccef5bb7aa0f10a9c7673e888f39bbade32f444b4b8a5cf2f172","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"5931249a-bae9-5900-a72f-4f8a1b0e5834","text":"To change its subject","isCorrect":false,"position":0},{"id":"62dd38fd-0953-5810-9961-31b935443d2f","text":"To replace registration","isCorrect":false,"position":1},{"id":"ba7b8bd2-d1f5-55