":"application","difficulty":"medium","cognitive":"application","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"7c1f60dc6917d4af7eeb7f5bc7e9c6c887bb4e1d95e7015cacdfa16d05863b0c","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"efd4f6db-287f-5150-a1fa-4fe97972bfa3","text":"Remove it secretly","isCorrect":false,"position":0},{"id":"a229dd88-6641-54de-8a8b-ff412878e149","text":"Erase its reserve label","isCorrect":false,"position":1},{"id":"dcf5db75-bea2-508e-8e0a-97c63fb60cd8","text":"Substitute a borrower's card without permission","isCorrect":false,"position":2},{"id":"56e41753-8988-53e8-b298-d16366728f3f","text":"Ask staff whether an authorized short-loan option exists","isCorrect":true,"position":3}]},{"id":"3f17c7e4-e423-5ad5-8d76-fc7098f1bbe2","position":174,"prompt":"A user accidentally damages a book and hides it. Which response would better protect access and accountability?","explanation":"Early reporting supports preservation and fair resolution.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"27a7521db6cc4982a7b30ec455198a77edd8b85a9f689a8810a3cf15225fa93f","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"f9a5fe6a-23dc-5e37-ad7d-f929648f99de","text":"Remove more pages to conceal it","isCorrect":false,"position":0},{"id":"ac66f03b-2320-5019-91da-8e1a8e8de901","text":"Delete its catalogue record","isCorrect":false,"position":1},{"id":"b4b9eb6a-05d9-5841-ac08-c5d41748b2f7","text":"Report the damage promptly so staff can assess repair or replacement","isCorrect":true,"position":2},{"id":"5c90ea63-db73-5ba9-8df2-e5367863cb6a","text":"Return it anonymously to another shelf","isCorrect":false,"position":3}]},{"id":"dcffdc82-1ec5-558c-9f50-38c06d3c5662","position":175,"prompt":"A library introduces quiet phone zones instead of a total phone ban. Which principle best explains the change while respecting the module's aim?","explanation":"The stable objective is an effective study environment; implementation can evolve with technology.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"115bc746419bf0f18fe38a692308525af097afa41b2e66a53433624da60762bf","studyRef":{"sourceLabel":"GNS 113 module, Study Session 8","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"GNS 113 module, Study Session 8","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"8426289d-a372-5045-882c-c1fab9d2e394","text":"Prohibit digital learning entirely","isCorrect":false,"position":0},{"id":"aa2ac4f1-5050-51a6-9e95-2c7eeff3dcf9","text":"Control disruption while adapting the rule to current learning needs","isCorrect":true,"position":1},{"id":"24a9ceb1-f446-50e5-b8dc-261b16256ba8","text":"Abandon all conduct standards","isCorrect":false,"position":2},{"id":"ee3e4e95-4299-5465-8ec2-f3b543e81577","text":"Permit calls everywhere at maximum volume","isCorrect":false,"position":3}]},{"id":"ea39a1d6-9ade-5a04-b35d-f9e8d4780f0e","position":176,"prompt":"What is plagiarism?","explanation":"Plagiarism misrepresents intellectual authorship.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Library Rules, Responsible Use and Information Ethics","fingerprint":"459e1330462ee7f7e0