,"text":"Assume the newest-looking page is correct","isCorrect":false,"position":0},{"id":"795c2db6-bb58-52ed-bf1e-60320a759b97","text":"Share it before checking","isCorrect":false,"position":1},{"id":"8f282e26-dd08-5797-83b3-9c8cc4bf3e6e","text":"Treat it cautiously and verify the claim with authoritative sources","isCorrect":true,"position":2},{"id":"668521bc-a151-56e5-b834-0aecd83a8d95","text":"Cite it as conclusive because it is online","isCorrect":false,"position":3}]},{"id":"4c7dd47c-223a-58bd-a2ed-e763ea217d5d","position":199,"prompt":"A search on 'youth unemployment in Nigeria' retrieves too little. Which revision is most likely to improve recall?","explanation":"A concept-group strategy such as (youth OR adolescents) AND (unemployment OR joblessness) can retrieve variant terminology.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"ICT, Automation, Electronic Resources and Information Literacy","fingerprint":"d7f5a7bf7cf2a6c07d1bfcdd54f0004338a7f3b8631ad39be5c8a04c8b32a4d6","studyRef":{"sourceLabel":"General GNS 113 enrichment: ICT, Automation, Electronic Resources and Information Literacy","sourceKind":"general_gns113","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_gns113_200_v1","sourceReference":"General GNS 113 enrichment: ICT, Automation, Electronic Resources and Information Literacy","contentAndAnswerCheckCompleted":true,"humanVerificationRequired":true},"options":[{"id":"1bb8827f-9740-5ded-8a94-2b813bc05975","text":"Search an unrelated phrase","isCorrect":false,"position":0},{"id":"6d88b4a3-c91c-5464-b294-4c0552236164","text":"Add synonyms with OR while retaining the main concepts","isCorrect":true,"position":1},{"id":"68edcffe-7a8d-5229-ac12-a205119a0021","text":"Require every possible term with AND","isCorrect":false,"position":2},{"id":"41d6227f-f89c-5e28-a931-0b63977d55c5","text":"Exclude Nigeria","isCorrect":false,"position":3}]}]$gns113_questions$::jsonb)
  LOOP
    INSERT INTO public.study_quiz_questions
      (id, set_id, prompt, explanation, question_type, position, question_kind,
       difficulty_level, cognitive_level, source_topic, question_fingerprint,
       study_ref, generation_meta, ai_generated, published, created_at)
    VALUES
      ((v_question->>'id')::uuid, v_set_id, v_question->>'prompt', v_question->>'explanation',
       'mcq', (v_question->>'position')::integer, v_question->>'questionKind',
       v_question->>'difficulty', v_question->>'cognitive', v_question->>'topic',
       v_question->>'fingerprint', v_question->'studyRef', v_question->'generationMeta',
       false, true, now());

    FOR v_option IN
      SELECT value FROM jsonb_array_elements(v_question->'options')
    LOOP
      INSERT INTO public.study_quiz_options
        (id, question_id, text, is_correct, position, created_at)
      VALUES
        ((v_option->>'id')::uuid, (v_question->>'id')::uuid, v_option->>'text',
         (v_option->>'isCorrect')::boolean, (v_option->>'position')::integer, now());
    END LOOP;
  END LOOP;

  UPDATE public.study_quiz_sets
  SET questions_count = 200,
      exam_question_count = 40,
      time_limit_minutes = 40,
      published = false,
      visibility = 'private',
      updated_at = now()
  WHERE id = v_set_id;
END
$import$;

COMMIT;

-- Expected: 200 questions, 800 options, 200 correct options, 0 verified before admin review.
SELECT
  s.id AS set_id,
  s.title,
  count(DISTINCT q.id) AS questions,
  count(o.id) AS options,
  count(o.id) FILTER (WHERE o.is_correct) AS correct_options,
  count(DISTINCT q.id) FILTER (WHERE q.exam_verified_at IS NOT NULL) AS verified_questions
FROM public.study_quiz_sets s
LEFT JOIN public.study_quiz_questions q ON coalesce(q.set_id, q.quiz_set_id) = s.id
LEFT JOIN public.study_quiz_options o ON o.question_id = q.id
WHERE upper(regexp_replace(coalesce(s.course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'GNS113'
  AND s.delivery_mode = 'mock_exam'
  AND s.exam_campaign_key = 'supplementary-2026'
GROUP BY s.id, s.title;
